// ─────────────────────────────────────────────────────────────────────────────
// CLI Entry Point
// ─────────────────────────────────────────────────────────────────────────────

function main() {
  const args = process.argv.slice(2);
  const applyChanges = args.includes('--apply');
  const jsonOutput = args.includes('--json');
  const useSample = args.includes('--sample');

  console.log('═══════════════════════════════════════════════════════════════');
  console.log('  T5.7: Post-Prod Telemetry Feedback');
  console.log('═══════════════════════════════════════════════════════════════');

  // Load production telemetry
  let prodData = loadProdTelemetry();

  if (!prodData) {
    if (useSample) {
      prodData = generateSampleProdTelemetry();
    } else {
      console.log('\nNo prod-telemetry.json found.');
      console.log('Use --sample flag to generate sample data for demonstration.');
      console.log('\nExpected format:');
      console.log(JSON.stringify({
        version: '1.0',
        collectedAt: '2026-03-16T00:00:00Z',
        environment: 'production',
        selectors: [
          {
            selector: '[data-testid="example"]',
            totalRuns: 1000,
            successes: 990,
            failures: 10,
            consecutiveSuccessDays: 7,
            environments: ['production'],
          },
        ],
      }, null, 2));
      process.exit(0);
    }
  }

  // Load lifecycle
  const lifecycle = loadLifecycle();

  if (!lifecycle) {
    console.log('\nNo .caf-selector-lifecycle.json found.');
    console.log('Run npm run ci:lifecycle first to initialize lifecycle tracking.');
  }

  // Generate report
  const report = generateReport(prodData, lifecycle);

  // Output
  if (jsonOutput) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    printConsoleReport(report);
  }

  // Save report
  fs.writeFileSync(OUTPUT_FILE, JSON.stringify(report, null, 2));

  if (!jsonOutput) {
    console.log(`\n✓ Report saved to ${OUTPUT_FILE}`);
  }

  // Apply changes to lifecycle
  if (applyChanges && lifecycle) {
    const updated = applyFeedbackToLifecycle(lifecycle, report.actions);
    if (updated > 0) {
      console.log(`✓ Applied ${updated} lifecycle state change(s)`);
    } else {
      console.log('○ No lifecycle changes to apply');
    }
  } else if (applyChanges) {
    console.log('⚠ Cannot apply changes: no lifecycle data found');
  }
}

// Guard CLI entry point
if (require.main === module) {
  main();
}

// Exports for testing
export { analyzeSelector, generateRecommendations, FeedbackReport, FeedbackAction };
